              geo:hasGeometry ?g2 .
          ?c2 hyobs:hasCatchmentAreaKm2 ?areaQ2 .
          ?areaQ2 qudt:numericValue ?areaKm2_2 .

          FILTER(?areaKm2_2 > ?areaKm2)
