PREFIX sosa: <http://www.w3.org/ns/sosa/>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?catchment ?aridityIndex ?meanElevation
WHERE {
  GRAPH <hydroturtle/quadica> {
    ?catchment a envthes:30212 ;
      hyobs:hasCatchmentAreaKm2 ?areaQty ;
      hyobs:aridityIndex ?aridityIndex ;
      hyobs:meanElevation ?meanElevation .

    ?areaQty a qudt:QuantityValue ;
      qudt:numericValue ?areaKm2 .

    FILTER(?areaKm2 > 50)
  }
}

